import sharp from 'sharp';
import { readFile, writeFile } from 'fs/promises';
import { join } from 'path';

// Rasterise the brand logo + wordmark, and derive black / white colourways from
// the default (brand brown) source SVGs.
//   default → PNG (transparent) + JPG (on cream)
//   black   → SVG + PNG (transparent)
//   white   → SVG + PNG (transparent)
//
// Then emit the three head assets BaseLayout links to: og-default.jpg,
// apple-touch-icon.png and favicon.ico.
//
// Every raster output is gitignored and regenerated by `prebuild`, so run
// `npm run build` (or this script) once before `astro dev` if you need them
// served locally.

const BRAND_DIR = new URL('../public/brand/', import.meta.url).pathname;
const PUBLIC_DIR = new URL('../public/', import.meta.url).pathname;
const ASSETS_DIR = new URL('../src/assets/', import.meta.url).pathname;
const SIZE = 1024;
const BRAND_HEX = /#713b2a/gi; // the only visible colour in both source SVGs

const BASES = ['mors-logo', 'mors-wordmark'];
const COLORWAYS = [
  { suffix: '', color: null },          // default — keep the source brown
  { suffix: '-black', color: '#000000' },
  { suffix: '-white', color: '#ffffff' },
];

let count = 0;
for (const base of BASES) {
  const isWide = base.includes('wordmark');
  const width = isWide ? SIZE * 4 : SIZE;
  const height = SIZE;
  const baseSvg = await readFile(join(BRAND_DIR, `${base}.svg`), 'utf8');

  for (const { suffix, color } of COLORWAYS) {
    const name = `${base}${suffix}`;
    let svg = baseSvg;
    if (color) {
      // Recolour the visible marks and write the variant SVG as a real asset.
      svg = baseSvg.replace(BRAND_HEX, color);
      await writeFile(join(BRAND_DIR, `${name}.svg`), svg, 'utf8');
    }
    const svgBuf = Buffer.from(svg);

    // PNG — transparent background for every colourway.
    await sharp(svgBuf)
      .resize(width, height, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
      .png()
      .toFile(join(BRAND_DIR, `${name}.png`));

    // JPG — only the default colourway (JPG has no transparency; on cream).
    if (!color) {
      await sharp(svgBuf)
        .resize(width, height, { fit: 'contain', background: { r: 245, g: 240, b: 232, alpha: 1 } })
        .flatten({ background: { r: 245, g: 240, b: 232 } })
        .jpeg({ quality: 95 })
        .toFile(join(BRAND_DIR, `${name}.jpg`));
    }
    console.log(`  ✓ ${name}`);
    count++;
  }
}

// ---- Head assets referenced by BaseLayout ------------------------------
// og:image, favicon.ico and apple-touch-icon.png are all linked from every
// page, so they have to exist or each one is a 404 and link previews come out
// blank.

// Social card: the facade photo is the most inviting frame we have. 1200x630
// is the size Facebook/LinkedIn/Slack/iMessage all crop to.
await sharp(join(ASSETS_DIR, 'mors-facade.jpg'))
  .resize(1200, 630, { fit: 'cover', position: 'bottom' })
  .jpeg({ quality: 82, mozjpeg: true })
  .toFile(join(PUBLIC_DIR, 'og-default.jpg'));
console.log('  ✓ og-default.jpg');

// iOS home-screen icon. It ignores alpha, so flatten onto cream rather than
// letting it composite against black.
const logoSvg = await readFile(join(BRAND_DIR, 'mors-logo.svg'));
await sharp(logoSvg)
  .resize(180, 180, { fit: 'contain', background: { r: 245, g: 240, b: 232, alpha: 1 } })
  .flatten({ background: { r: 245, g: 240, b: 232 } })
  .png()
  .toFile(join(PUBLIC_DIR, 'apple-touch-icon.png'));
console.log('  ✓ apple-touch-icon.png');

// favicon.ico — sharp has no ICO encoder, but the ICO container is allowed to
// hold a PNG payload verbatim, so wrap a 32x32 PNG in the 22-byte header.
const iconPng = await sharp(logoSvg)
  .resize(32, 32, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
  .png()
  .toBuffer();
const ico = Buffer.alloc(22 + iconPng.length);
ico.writeUInt16LE(0, 0);              // reserved
ico.writeUInt16LE(1, 2);              // type: icon
ico.writeUInt16LE(1, 4);              // one image
ico.writeUInt8(32, 6);                // width
ico.writeUInt8(32, 7);                // height
ico.writeUInt8(0, 8);                 // palette size (0 = truecolour)
ico.writeUInt8(0, 9);                 // reserved
ico.writeUInt16LE(1, 10);             // colour planes
ico.writeUInt16LE(32, 12);            // bits per pixel
ico.writeUInt32LE(iconPng.length, 14);// payload size
ico.writeUInt32LE(22, 18);            // payload offset
iconPng.copy(ico, 22);
await writeFile(join(PUBLIC_DIR, 'favicon.ico'), ico);
console.log('  ✓ favicon.ico');

console.log(`Generated ${count} brand colourway asset sets + 3 head assets`);
